package com.recycleconnect.files;

import java.io.IOException;
import java.io.InputStream;

/**
 * Where uploaded files live. {@link LocalFileStorage} writes to disk for development; a free-tier S3-compatible
 * store can replace it by implementing this interface (docs/EXTENDING.md). Keys are opaque, generated by us.
 */
public interface FileStorage {

    /** Stores the bytes and returns the key to read them back. */
    String save(byte[] bytes, String extension) throws IOException;

    InputStream open(String key) throws IOException;

    void delete(String key) throws IOException;
}
